  "This repository has more people with access than are listed here. Ask for the rest on the host.":
    "此处仅列出部分有访问权限的人员，请在托管平台邀请其他人员。",
  "Changing labels needs triage access on this repository": "修改标签需要此仓库的分诊权限",
  "This repository has no labels.": "此仓库没有标签。",
  "No label matches that.": "没有匹配的标签。",
