  "This repository has more labels than are listed here. Apply the rest on the host.":
    "此处仅列出部分标签，请在托管平台应用其他标签。",
  "The host refused it. Check that you have triage access on this repository.":
    "托管平台拒绝了此操作，请确认你拥有此仓库的分诊权限。",
  "The host refused it. Check that you have write access on this repository, and that they still have access to it.":
    "托管平台拒绝了此操作，请确认你拥有此仓库的写入权限，且受邀人员仍有访问权限。",
  "The host refused the merge. Check that you have write access, that the checks it requires have passed, and that the branch is not conflicting.":
    "托管平台拒绝了合并。请确认你拥有写入权限、必需检查已通过，且分支没有冲突。",
  "The host refused it. Check that you have write access to this repository.":
    "托管平台拒绝了此操作，请确认你拥有此仓库的写入权限。",
  "The host refused it. Check that you have write access, or that you opened it.":
    "托管平台拒绝了此操作，请确认你拥有写入权限或是此请求的创建者。",
  "The host refused it. Check that you have write access, and that the branch still exists.":
    "托管平台拒绝了此操作，请确认你拥有写入权限且分支仍然存在。",
  "The host refused it. Check that you have write access to the branch (a fork branch also needs its author to allow edits from maintainers), and that it does not conflict with the base.":
    "托管平台拒绝了此操作，请确认你有分支写入权限且与目标分支没有冲突。派生仓库分支还需要作者允许维护者编辑。",
  "The host refused it. Check that this repository allows auto-merge, that you have write access, and that there is something left for it to wait on.":
    "托管平台拒绝了此操作，请确认仓库允许自动合并、你拥有写入权限，且仍有待满足的合并条件。",
  "The host refused it. Check that auto-merge is enabled for this repository and that you have write access.":
    "托管平台拒绝了此操作，请确认仓库已启用自动合并，且你拥有写入权限。",
  "The host refused it. Check that you have write access, and that the merge has not already happened.":
    "托管平台拒绝了此操作，请确认你拥有写入权限且请求尚未合并。",
  "The host refused it. Check that you have write access and that this {term} was merged on the host.":
    "托管平台拒绝了此操作，请确认你拥有写入权限，且此{term}已在托管平台合并。",
  "The host refused it. Check that you have write access to the source repository and that the branch has not moved since this page loaded.":
    "托管平台拒绝了此操作，请确认你拥有源仓库的写入权限，且页面加载后分支没有更新。",
  "The host refused it. Check that you have Actions write access and that these workflow runs are still awaiting approval.":
    "托管平台拒绝了此操作，请确认你拥有 Actions 写入权限，且这些工作流仍在等待批准。",
  "The host refused it. Check that you have write access, and that the base branch has not diverged in a way the host cannot merge.":
    "托管平台拒绝了此操作，请确认你拥有写入权限，且目标分支未出现托管平台无法合并的分歧。",
